using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnStartOfBattleLoseAtFirstTurnOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnStartOfBattleLoseAtFirstTurn Omen Data")]
public class OnStartOfBattleLoseAtFirstTurnOmenData : OnStartOfBattleOmenData
{
	private const string startFirstTurnChantID = "EndOfPlayerFirstTurnChant";

	[SerializeField]
	private DefaultEffectAction defaultEffectAction;

	public override string OmenConvertedDescription()
	{
		string startOfBattleLocalizedDescription = GetStartOfBattleLocalizedDescription();
		string text = defaultEffectAction.GetActionDescription(ActionValue).LowercaseFirst();
		LocalizationManager instance = ReferenceSingleton<LocalizationManager>.Instance;
		return startOfBattleLocalizedDescription + instance.GetLocalizedSpace() + text + "\n" + instance.GetLocalizedString("EndOfPlayerFirstTurnChant") + instance.GetLocalizedSpace() + instance.GetLocalizedDecreaseEffect(defaultEffectAction.Effect, ActionValue).LowercaseFirst();
	}
}
